// The checker side of src/oracle.ts: a TypeScript 7.1 type reduced to the shape src/oracle-compare.ts compares,
// once per type id and depth.
import { SignatureKind, SymbolFlags, TypeFlags } from 'typescript-beta/sync'
import { isBareObject, lit, MAX_DEPTH, prim, type LiteralKind, type Norm } from './oracle-compare.ts'

const ANONYMOUS = new Set(['__type', '__object', '__function', '__call', ''])

const INTRINSICS: [number, string][] = [
  [TypeFlags.Any, 'any'],
  [TypeFlags.Unknown, 'unknown'],
  [TypeFlags.String, 'string'],
  [TypeFlags.Number, 'number'],
  [TypeFlags.BigInt, 'bigint'],
  [TypeFlags.ESSymbol, 'symbol'],
  [TypeFlags.Null, 'null'],
  [TypeFlags.Undefined, 'undefined'],
  [TypeFlags.Void, 'void'],
  [TypeFlags.Never, 'never'],
  [TypeFlags.NonPrimitive, 'object'],
  // A pattern such as `var(--${string})` or `Uppercase<string>` stands for strings.
  [TypeFlags.TemplateLiteral | TypeFlags.StringMapping, 'string'],
]

const LITERAL_FLAGS: [number, LiteralKind][] = [
  [TypeFlags.StringLiteral, 'string'],
  [TypeFlags.NumberLiteral, 'number'],
  [TypeFlags.BigIntLiteral, 'bigint'],
]

/** The checker's name for a type: its alias, or the interface, class or enum that declares it. */
function typeName(t: any): string | undefined {
  const alias = t.getAliasSymbol()
  if (alias && !ANONYMOUS.has(alias.name)) return alias.name
  if (t.flags & (TypeFlags.Object | TypeFlags.Enum | TypeFlags.EnumLiteral)) {
    const symbol = t.getSymbol()
    if (symbol && !ANONYMOUS.has(symbol.name)) return symbol.name
  }
  return undefined
}

/** A normalizer bound to one checker, caching by type id and depth. */
export function checkerNormalizer(checker: any): (t: any) => Norm {
  const cache = new Map<string, Norm>()

  function norm(t: any, depth = 0): Norm {
    const key = `${t.id}:${depth}`
    const cached = cache.get(key)
    if (cached) return cached
    const result = uncached(t, depth)
    cache.set(key, result)
    return result
  }

  function scalar(t: any): Norm | undefined {
    const f: number = t.flags
    if (t.isErrorType()) return { k: 'error' }
    if (f & TypeFlags.Boolean) return { ...prim('boolean'), alias: typeName(t) }
    const intrinsic = INTRINSICS.find(([flag]) => f & flag)
    if (intrinsic) return prim(intrinsic[1])
    // The beta's responses carry neither `value` nor `intrinsicName` for `true` and `false`.
    if (f & TypeFlags.BooleanLiteral) return lit(checker.typeToString(t), 'boolean')
    const of = LITERAL_FLAGS.find(([flag]) => f & flag)?.[1]
    if (of) return lit(String(t.value), of)
    return undefined
  }

  /** A type parameter with what Caliper may have put in its place: its default, and its constraint. */
  const expanding = new Set<number>()
  function typeParameter(t: any, depth: number): Norm {
    const name: string = t.getSymbol()?.name ?? ''
    // A parameter inside its own default or constraint (`T extends Foo<T>`) is its name.
    if (expanding.has(t.id)) return { k: 'param', name }
    expanding.add(t.id)
    // Its instances sit one level down, but never past the depth limit, where a scalar one still reads.
    const at = Math.min(depth + 1, MAX_DEPTH)
    const read = (get: () => any): Norm | undefined => {
      try {
        const type = get()
        return type ? norm(type, at) : undefined
      } catch {
        return undefined
      }
    }
    try {
      return {
        k: 'param',
        name,
        fallback: read(() => checker.getDefaultFromTypeParameter(t)),
        constraint: read(() => checker.getBaseConstraintOfType(t)),
      }
    } finally {
      expanding.delete(t.id)
    }
  }

  function union(t: any, depth: number, alias: string | undefined): Norm {
    const parts: Norm[] = (t.getTypes() ?? []).map((m: any) => norm(m, depth + 1))
    // An optional prop's `StyleProp<X> | undefined` is a new union without an alias; the type without `undefined`
    // keeps it, as TypeScript prints it.
    const optionalAlias =
      alias === undefined && parts.some((m) => m.k === 'prim' && m.name === 'undefined')
        ? typeName(checker.getNonNullableType(t))
        : undefined
    return { k: 'union', members: parts, alias: alias ?? optionalAlias }
  }

  function intersection(t: any, depth: number, alias: string | undefined): Norm {
    const parts: Norm[] = (t.getTypes() ?? []).map((m: any) => norm(m, depth + 1))
    // `string & {}` (the keep-the-literals trick) is a string.
    const meaningful = parts.filter((m) => !isBareObject(m))
    if (meaningful.length === 1) return { ...meaningful[0], alias: alias ?? meaningful[0].alias }
    return { k: 'intersection', members: parts, alias }
  }

  function object(t: any, depth: number, alias: string | undefined): Norm {
    if (checker.isArrayType(t)) {
      const [element] = checker.getTypeArguments(t)
      return { k: 'array', element: element ? norm(element, depth + 1) : { k: 'opaque' }, alias }
    }
    if (checker.isTupleType(t)) {
      return { k: 'tuple', elements: checker.getTypeArguments(t).map((e: any) => norm(e, depth + 1)), alias }
    }
    const properties = checker.getPropertiesOfType(t)
    const [sig] = checker.getSignaturesOfType(t, SignatureKind.Call)
    if (sig && properties.length === 0) {
      const params = sig.getParameters()
      const paramTypes = params.length > 0 ? checker.getTypeOfSymbol(params) : []
      return {
        k: 'function',
        params: params.map((p: any, i: number) => ({
          optional: Boolean(p.flags & SymbolFlags.Optional),
          rest: sig.hasRestParameter && i === params.length - 1,
          type: norm(paramTypes[i], depth + 1),
        })),
        returns: norm(checker.getReturnTypeOfSignature(sig), depth + 1),
        alias,
      }
    }
    const infos = checker.getIndexInfosOfType(t)
    const indexValues: Norm[] = infos.map((info: any) => norm(info.valueType, depth + 1))
    return {
      k: 'object',
      fields: properties.map((p: any) => p.name).toSorted(),
      index: infos.length > 0,
      ...(infos.length > 0 && {
        indexValue: indexValues.length === 1 ? indexValues[0] : { k: 'union', members: indexValues },
      }),
      alias,
    }
  }

  function uncached(t: any, depth: number): Norm {
    if (t.flags & TypeFlags.TypeParameter) return typeParameter(t, depth)
    const known = scalar(t)
    if (known) return known
    const alias = typeName(t)
    if (depth >= MAX_DEPTH) return { k: 'opaque', alias }
    if (t.flags & TypeFlags.Union) return union(t, depth, alias)
    if (t.flags & TypeFlags.Intersection) return intersection(t, depth, alias)
    if (t.flags & TypeFlags.Object) return object(t, depth, alias)
    return { k: 'opaque', alias }
  }

  return (t: any) => norm(t)
}
// The structural comparison behind src/oracle.ts: both sides' prop types reduced to one shape, and one verdict per
// pair. Pure: nothing here talks to the checker.

/** The primitive a literal is a value of: `"0"` and `0` spell the same `value` and are two types. */
export type LiteralKind = 'string' | 'number' | 'bigint' | 'boolean'

/** A type reduced to what both sides can state: kind, literal value, members, fields, parameters. `alias` is the
 * checker's name for it (an alias, or the interface that declares it), which Caliper may print instead. */
export type Norm = (
  | { k: 'prim'; name: string }
  | { k: 'lit'; value: string; of: LiteralKind }
  | { k: 'union'; members: Norm[] }
  | { k: 'intersection'; members: Norm[] }
  | { k: 'array'; element: Norm }
  | { k: 'tuple'; elements: Norm[] }
  | { k: 'function'; params: { optional: boolean; rest: boolean; type: Norm }[]; returns: Norm }
  | { k: 'object'; fields: string[]; index: boolean; indexValue?: Norm }
  | { k: 'name'; name: string }
  | { k: 'param'; name: string; fallback?: Norm; constraint?: Norm }
  | { k: 'opaque' }
  | { k: 'error' }
) & { alias?: string }

export type Verdict = 'identical' | 'spelled' | 'less precise' | 'wrong' | 'checker any/error'

export const MAX_DEPTH = 3
export const VERDICTS: Verdict[] = ['identical', 'spelled', 'less precise', 'wrong', 'checker any/error']
const RANK: Verdict[] = ['identical', 'spelled', 'less precise', 'wrong']

/** A type name without `React.` or a namespace qualifier. */
export const bareName = (name: string) => name.replace(/^.*\./, '')
export const prim = (name: string): Norm => ({ k: 'prim', name })
export const lit = (value: string, of: LiteralKind): Norm => ({ k: 'lit', value, of })

/** `{}`: an object with no property and no index signature. The one place that decides it, for every reader of a
 * `Norm`: an index-only object (`{ [key: string]: V }`) has no fields either, and is not empty. */
export const isBareObject = (m: Norm) => m.k === 'object' && m.fields.length === 0 && !m.index

const TERMINALS: Record<string, string> = {
  reactNode: 'ReactNode',
  cssProperties: 'CSSProperties',
  elementType: 'ElementType',
  htmlAttributes: 'HTMLAttributes',
  ref: 'Ref',
  sxProps: 'SxProps',
}
const PRIMITIVES = new Set(['string', 'number', 'boolean', 'null', 'undefined', 'any', 'unknown', 'never', 'void'])
const LITERAL_KINDS: Record<string, LiteralKind> = {
  stringLiteral: 'string',
  numberLiteral: 'number',
  boolLiteral: 'boolean',
}
const LITERALS = new Set(Object.keys(LITERAL_KINDS))

const isIndexField = (field: any) => field.indexKey !== undefined

/** Caliper's canonical `PropType` JSON, normalized. */
export function caliperNorm(t: any, depth = 0): Norm {
  if (!t || depth > MAX_DEPTH) return { k: 'opaque' }
  if (PRIMITIVES.has(t.kind)) return prim(t.kind)
  if (LITERALS.has(t.kind)) return lit(String(t.value), LITERAL_KINDS[t.kind])
  const inner = (m: any) => caliperNorm(m, depth + 1)
  switch (t.kind) {
    case 'literalUnion': {
      return { k: 'union', members: t.members.map((m: string) => lit(m, 'string')) }
    }
    case 'union': {
      return { k: 'union', members: t.members.map((m: any) => inner(m)) }
    }
    case 'intersection': {
      const parts: Norm[] = t.members.map((m: any) => inner(m))
      const meaningful = parts.filter((m) => !isBareObject(m))
      return meaningful.length === 1 ? meaningful[0] : { k: 'intersection', members: parts }
    }
    case 'array': {
      return { k: 'array', element: inner(t.element) }
    }
    case 'tuple': {
      return { k: 'tuple', elements: (t.elements ?? t.members ?? []).map((m: any) => inner(m)) }
    }
    case 'object': {
      // Caliper writes an index signature as one field whose `indexKey` is the key type: its name is the signature's
      // parameter name (`[id: string]: number`), not a property.
      const indexed: any[] = t.fields.filter(isIndexField)
      const named: any[] = t.fields.filter((field: any) => !isIndexField(field))
      const indexValues: Norm[] = indexed.map((field) => inner(field.propType))
      return {
        k: 'object',
        fields: named.map((field) => field.name).toSorted(),
        index: indexed.length > 0,
        ...(indexed.length > 0 && {
          indexValue: indexValues.length === 1 ? indexValues[0] : { k: 'union', members: indexValues },
        }),
      }
    }
    // A `readonly` array or tuple is the array or tuple, as the checker reads it.
    case 'readonly': {
      return caliperNorm(t.element, depth)
    }
    case 'function': {
      const params = (t.params ?? []).map((p: any) => ({
        optional: p.optional === true,
        rest: p.rest === true,
        type: inner(p.type),
      }))
      return { k: 'function', params, returns: inner(t.returnType) }
    }
    case 'named': {
      return { k: 'name', name: bareName(t.name) }
    }
    default: {
      return TERMINALS[t.kind] ? { k: 'name', name: TERMINALS[t.kind] } : { k: 'opaque' }
    }
  }
}

const worst = (vs: Verdict[]): Verdict => vs.reduce((a, b) => (RANK.indexOf(b) > RANK.indexOf(a) ? b : a), 'identical')
const best = (vs: Verdict[]): Verdict => vs.reduce((a, b) => (RANK.indexOf(b) < RANK.indexOf(a) ? b : a), 'wrong')
const isBool = (n: Norm, value: string) => n.k === 'lit' && n.of === 'boolean' && n.value === value
const isUndefined = (m: Norm) => m.k === 'prim' && m.name === 'undefined'
const WIDENING = new Set(['string', 'number', 'boolean'])

/** An empty object type, or `Record<…>` (its arguments are not kept): what `string & {}` intersects with. */
const isEmptyObject = (m: Norm) => isBareObject(m) || (m.k === 'name' && m.name === 'Record')

/** Whether `m` is the primitive `name`, or `name & {}`, or a union with either. */
function absorbs(m: Norm, name: string): boolean {
  if (m.k === 'prim') return m.name === name
  if (m.k === 'union') return m.members.some((member) => absorbs(member, name))
  return m.k === 'intersection' && m.members.some(isEmptyObject) && m.members.some((member) => absorbs(member, name))
}

/** A name or opaque type that Caliper (or the checker) did not expand: what it holds is unknown, so no member beside it
 * can prove the other side wrong. */
const isUnexpanded = (m: Norm) => m.k === 'name' || m.k === 'opaque'

/** Union members without `undefined` (an optional prop's, which both sides treat as optional), flattened, with
 * `true | false` as `boolean`. */
function members(n: Norm, coverLiterals = false): Norm[] {
  const flat: Norm[] = []
  const push = (m: Norm) => {
    if (m.k === 'union') m.members.forEach(push)
    // An optional generic prop reads `T | (undefined & T)`.
    else if (!isUndefined(m) && !(m.k === 'intersection' && m.members.some(isUndefined))) flat.push(m)
  }
  push(n)
  // `'default' | 'large' | string` is `string` to the checker: a literal that a primitive of its kind in the same
  // union already covers adds nothing, so a union written with it holds the same values as one without. The checker's
  // `"blue" | … | (string & {})` keeps its literals for the reader, so `compare` scores it spelled, not identical. A
  // literal is covered by the primitive of its own kind only: `"0"` is not covered by `number`, `true` not by `string`.
  // `string & {}` and `string & Record<never, never>` (the `LiteralUnion` spellings) are `string` for this purpose.
  const has = (name: string) => flat.some((m) => absorbs(m, name))
  const covered = (m: Norm) => coverLiterals && m.k === 'lit' && has(m.of)
  const kept = flat.filter((m) => !covered(m))
  if (kept.some((m) => isBool(m, 'true')) && kept.some((m) => isBool(m, 'false'))) {
    return [...kept.filter((m) => !isBool(m, 'true') && !isBool(m, 'false')), prim('boolean')]
  }
  return kept
}

/** Two unions: each checker member covered by one of Caliper's (a missing member makes Caliper's type too narrow),
 * and each of Caliper's matched by one of the checker's (an extra member makes it too wide, unless it widens
 * literals). */
function compareUnions(cm: Norm[], km: Norm[], depth: number): Verdict {
  const kCovered = km.map((m) => best(cm.map((cMember) => compare(cMember, m, depth + 1))))
  const cMatched = cm.map((m) => {
    const verdict = best(km.map((kMember) => compare(m, kMember, depth + 1)))
    const widens =
      m.k === 'prim' &&
      WIDENING.has(m.name) &&
      km.some((kMember) => kMember.k === 'lit' || (kMember.k === 'prim' && kMember.name === m.name))
    return verdict === 'wrong' && widens ? 'less precise' : verdict
  })
  const verdict = worst([...kCovered, ...cMatched])
  // A union with a name or opaque member (`MantineColor | 'initials'`, a template literal) may hold the other side's
  // values in that member, so a member it cannot match is not proof of a different type.
  return verdict === 'wrong' && [...cm, ...km].some((m) => isUnexpanded(m)) ? 'less precise' : verdict
}

function compareFunctions(c: Norm & { k: 'function' }, k: Norm & { k: 'function' }, depth: number): Verdict {
  const verdicts: Verdict[] = [compare(c.returns, k.returns, depth + 1)]
  for (const [i, kp] of k.params.entries()) {
    const cp = c.params[i]
    if (cp === undefined) {
      verdicts.push(kp.optional || kp.rest ? 'less precise' : 'wrong')
    } else {
      verdicts.push(compare(cp.type, kp.type, depth + 1))
      // A marker the checker has and this side lost.
      if ((kp.optional && !cp.optional) || (kp.rest && !cp.rest)) verdicts.push('less precise')
    }
  }
  if (c.params.length > k.params.length) verdicts.push('wrong')
  return worst(verdicts)
}

/** One non-union type against another. */
function compareOne(c: Norm, k: Norm, depth: number): Verdict {
  switch (k.k) {
    case 'prim': {
      return c.k === 'prim' && c.name === k.name ? 'identical' : 'wrong'
    }
    case 'lit': {
      if (c.k === 'lit') return c.value === k.value && c.of === k.of ? 'identical' : 'wrong'
      return c.k === 'prim' && WIDENING.has(c.name) ? 'less precise' : 'wrong'
    }
    case 'array': {
      return c.k === 'array' ? compare(c.element, k.element, depth + 1) : 'wrong'
    }
    case 'tuple': {
      if (c.k !== 'tuple') return c.k === 'array' ? 'less precise' : 'wrong'
      if (c.elements.length !== k.elements.length) return 'wrong'
      return worst(c.elements.map((e, i) => compare(e, k.elements[i], depth + 1)))
    }
    case 'function': {
      return c.k === 'function' ? compareFunctions(c, k, depth) : 'wrong'
    }
    case 'object': {
      if (c.k !== 'object') return c.k === 'prim' && c.name === 'object' ? 'less precise' : 'wrong'
      const own = new Set(c.fields)
      if (c.fields.some((f) => !k.fields.includes(f))) return 'wrong'
      // An index signature Caliper has and the checker does not describes a different type.
      if (c.index && !k.index) return 'wrong'
      const verdicts: Verdict[] = [
        k.fields.some((f) => !own.has(f)) || (k.index && !c.index) ? 'less precise' : 'identical',
      ]
      // Both state an index: its value type is compared, and one a side does not state is not proof of agreement.
      if (c.index && k.index) {
        verdicts.push(c.indexValue && k.indexValue ? compare(c.indexValue, k.indexValue, depth + 1) : 'less precise')
      }
      return worst(verdicts)
    }
    case 'intersection': {
      if (c.k !== 'intersection') return 'less precise'
      return c.members.length === k.members.length ? 'identical' : 'less precise'
    }
    case 'param': {
      // A type parameter of the component itself, which Caliper replaced with an instantiation: its default, as a bare
      // `AccordionProps` means `AccordionProps<false>`, or its constraint. That is one instance of the parameter,
      // looser or narrower than the parameter itself, and not another type; a type that is neither instance is.
      // `c` may be one member of a union Caliper wrote out (`string` of `string | number`), so it must fit one member of
      // an instance, not all of them.
      const instances = [k.fallback, k.constraint].filter((i): i is Norm => i !== undefined).flatMap((i) => members(i))
      // A parameter with neither (a generic component cast over `forwardRef`, whose props interface declares the
      // default) leaves the checker no instance to hold Caliper's to: any one it picked is one value of the parameter.
      if (instances.length === 0) return 'less precise'
      return instances.some((i) => compare(c, i, depth + 1) !== 'wrong') ? 'less precise' : 'wrong'
    }
    default: {
      return 'wrong'
    }
  }
}

/** How Caliper's normalized type `c` stands against the checker's `k`. A checker union that spells literals a
 * primitive in it already covers (`'a' | 'b' | (string & {})`) holds the values Caliper's `string` does, spelled
 * another way. */
export function compare(c: Norm, k: Norm, depth = 0): Verdict {
  const verdict = compareValues(c, k, depth)
  return verdict === 'identical' && members(k).length !== members(k, true).length ? 'spelled' : verdict
}

function compareValues(c: Norm, k: Norm, depth: number): Verdict {
  if (depth > MAX_DEPTH) return 'identical'
  // The checker has no type to compare with: an error, `any`, or a top-level `unknown` where Caliper has a type
  // (most often a declaration the program couldn't resolve).
  const uninformative =
    k.k === 'error' || (k.k === 'prim' && k.name === 'any') || (depth === 0 && k.k === 'prim' && k.name === 'unknown')
  if (uninformative && !(c.k === 'prim' && k.k === 'prim' && c.name === k.name)) {
    return depth === 0 ? 'checker any/error' : 'identical'
  }
  const km = members(k, true)
  // An optional prop of type `never` reads `undefined` in the checker, which `members` drops as the optional marker.
  if (km.length === 0 && c.k === 'prim' && c.name === 'never') return 'identical'
  if (c.k === 'name') {
    // An optional prop's checker type is `X | undefined`; the name is X's.
    const target = km.length === 1 ? km[0] : k
    if ((target.alias && bareName(target.alias) === c.name) || (k.alias && bareName(k.alias) === c.name)) {
      return 'spelled'
    }
    if (target.k === 'param' && target.name === c.name) return 'identical'
    // A name Caliper left unexpanded where the checker has the type itself (an unbound parameter, an alias that
    // resolves to another name).
    return 'less precise'
  }
  if (k.k === 'opaque') return 'identical'
  if (c.k === 'opaque') return 'less precise'
  if (c.k === 'prim' && (c.name === 'any' || c.name === 'unknown') && !(k.k === 'prim' && k.name === c.name)) {
    return 'less precise'
  }
  // An intersection Caliper left as written, which the checker reduced (`Mode & …` to a literal union).
  if (c.k === 'intersection' && !km.some((m) => m.k === 'intersection')) return 'less precise'
  const cm = members(c, true)
  if (cm.length !== 1 || km.length !== 1) return compareUnions(cm, km, depth)
  const [cOne] = cm
  const [kOne] = km
  if (cOne !== c || kOne !== k) return compare(cOne, { ...kOne, alias: kOne.alias ?? k.alias }, depth)
  return compareOne(c, k, depth)
}

// TypeScript 7.1's checker as a test oracle for Caliper's prop types (docs/parity.md). Test-only: the opt-in semantic
// backend is a separate, experimental feature.
//
// For one corpus, finds components the way react-docgen-typescript does (an exported function whose only or `props`
// parameter is the props type), reads each prop's type from the checker, and compares it structurally with the prop
// Caliper's canonical JSON reports for the same component (src/oracle-compare.ts). Each shared prop gets one verdict:
//
//   identical          both sides describe the same type
//   spelled            the same type, Caliper by name where the checker expands it, or the reverse
//   less precise       Caliper's type is looser or unevaluated (an opaque type, `string` for a literal union, a name
//                      left unexpanded, a lost optional or rest parameter, a missing field)
//   wrong              Caliper's type describes something else
//   checker any/error  the checker itself has no type (an unresolved import, `any`, or `unknown` where Caliper has one)
//
// Checker types are normalized once per type id and verdicts made once per (Caliper prop, checker type), so Chakra's
// ~470,000 props cost a few thousand distinct comparisons.
//
// With `--rdt` and `--rdg` (the dumps scripts/rdt.mjs and scripts/rdg.mjs write) the report also scores react-docgen-
// typescript and react-docgen over every own prop the checker finds (`tools`; src/tool-universe.ts).
import { readdirSync, readFileSync, realpathSync, writeFileSync } from 'node:fs'
import { join, relative } from 'node:path'
import { API } from 'typescript-beta/sync'
import { checkCaliperShape, flattenProps, requireComparison } from './caliper-input.ts'
import { exportName, propsTypeOf } from './checker-components.ts'
import { checkerNormalizer } from './oracle-checker.ts'
import { caliperNorm, compare, VERDICTS, type Norm, type Verdict } from './oracle-compare.ts'
import { assertSchemaVersion } from './schema-version.ts'
import { collapsedLayerFiles, loadTool, normComponent, pathKey, universeRecorder } from './tool-universe.ts'

const KEYS = ['root', 'src', 'tsconfig', 'caliper', 'out', 'files', 'dump', 'rows', 'missing', 'rdt', 'rdg'] as const
const args: Partial<Record<(typeof KEYS)[number], string>> = {}
for (let i = 2; i < process.argv.length; i += 2) {
